    moved=[(r+shift,c,v) for r,c,v in cells]
    for r,c,v in moved:
        g[r][c]=v
    stripe=min(r for r,c,v in moved)-1 if shift>0 else max(r for r,c,v in moved)+1
    if 0<=stripe<h:
        g[stripe]=[8]*w
